# pyright: standard
"""A statement generated by a macro call at a line of the open-code source."""

from __future__ import annotations

from typing import Literal

from pydantic import BaseModel, ConfigDict


class MacroOrigin(BaseModel):
    model_config = ConfigDict(frozen=True, extra="forbid")

    kind: Literal["MACRO"]
    file: str
    line: int
    macro: str
    depth: int
